script:
test('dimensional weight is length times width times height divided by 5000 and billable weight is the greater rounded weight not the greater raw weight', function () {
  assert.deepEqual(code.billableWeight({ lengthCm: 40, widthCm: 30, heightCm: 20, actualWeightKg: 3.2 }), {
    dimensionalWeightKg: 4.8,
    roundedDimensionalWeightKg: 5.0,
    roundedActualWeightKg: 3.5,
    billableWeightKg: 5.0
  });
});

test('an exact multiple of 0.5 stays unchanged and the rounded actual weight can be the greater one', function () {
  assert.deepEqual(code.billableWeight({ lengthCm: 10, widthCm: 10, heightCm: 10, actualWeightKg: 2.0 }), {
    dimensionalWeightKg: 0.2,
    roundedDimensionalWeightKg: 0.5,
    roundedActualWeightKg: 2.0,
    billableWeightKg: 2.0
  });
});

test('both weights are rounded and the billable weight is the greater rounded value rather than the greater raw value', function () {
  assert.deepEqual(code.billableWeight({ lengthCm: 20, widthCm: 20, heightCm: 20, actualWeightKg: 0.5 }), {
    dimensionalWeightKg: 1.6,
    roundedDimensionalWeightKg: 2.0,
    roundedActualWeightKg: 0.5,
    billableWeightKg: 2.0
  });
});

test('a non-exact actual weight rounds up to the next 0.5 and wins over the dimensional weight', function () {
  assert.deepEqual(code.billableWeight({ lengthCm: 15, widthCm: 10, heightCm: 10, actualWeightKg: 2.1 }), {
    dimensionalWeightKg: 0.3,
    roundedDimensionalWeightKg: 0.5,
    roundedActualWeightKg: 2.5,
    billableWeightKg: 2.5
  });
});

test('zero is an exact multiple of 0.5 and stays zero', function () {
  assert.deepEqual(code.billableWeight({ lengthCm: 0, widthCm: 0, heightCm: 0, actualWeightKg: 0 }), {
    dimensionalWeightKg: 0,
    roundedDimensionalWeightKg: 0.0,
    roundedActualWeightKg: 0.0,
    billableWeightKg: 0.0
  });
});

test('dimensions of one give the smallest positive integer volume and round the dimensional weight up', function () {
  assert.deepEqual(code.billableWeight({ lengthCm: 1, widthCm: 1, heightCm: 1, actualWeightKg: 0 }), {
    dimensionalWeightKg: 0.0002,
    roundedDimensionalWeightKg: 0.5,
    roundedActualWeightKg: 0.0,
    billableWeightKg: 0.5
  });
});

test('one step below the 0.5 kg boundary rounds up to 0.5', function () {
  assert.deepEqual(code.billableWeight({ lengthCm: 21, widthCm: 17, heightCm: 7, actualWeightKg: 0 }), {
    dimensionalWeightKg: 0.4998,
    roundedDimensionalWeightKg: 0.5,
    roundedActualWeightKg: 0.0,
    billableWeightKg: 0.5
  });
});

test('a value exactly on the 0.5 kg boundary stays 0.5', function () {
  assert.deepEqual(code.billableWeight({ lengthCm: 25, widthCm: 10, heightCm: 10, actualWeightKg: 0 }), {
    dimensionalWeightKg: 0.5,
    roundedDimensionalWeightKg: 0.5,
    roundedActualWeightKg: 0.0,
    billableWeightKg: 0.5
  });
});

test('one step above the 0.5 kg boundary rounds up to 1.0', function () {
  assert.deepEqual(code.billableWeight({ lengthCm: 2501, widthCm: 1, heightCm: 1, actualWeightKg: 0 }), {
    dimensionalWeightKg: 0.5002,
    roundedDimensionalWeightKg: 1.0,
    roundedActualWeightKg: 0.0,
    billableWeightKg: 1.0
  });
});

test('the closest producible value below the 0.25 halfway point still rounds up', function () {
  assert.deepEqual(code.billableWeight({ lengthCm: 1249, widthCm: 1, heightCm: 1, actualWeightKg: 0 }), {
    dimensionalWeightKg: 0.2498,
    roundedDimensionalWeightKg: 0.5,
    roundedActualWeightKg: 0.0,
    billableWeightKg: 0.5
  });
});

test('dimensional weight exactly at the 0.25 halfway point rounds up', function () {
  assert.deepEqual(code.billableWeight({ lengthCm: 25, widthCm: 10, heightCm: 5, actualWeightKg: 0 }), {
    dimensionalWeightKg: 0.25,
    roundedDimensionalWeightKg: 0.5,
    roundedActualWeightKg: 0.0,
    billableWeightKg: 0.5
  });
});

test('the closest producible value above the 0.25 halfway point rounds up', function () {
  assert.deepEqual(code.billableWeight({ lengthCm: 1251, widthCm: 1, heightCm: 1, actualWeightKg: 0 }), {
    dimensionalWeightKg: 0.2502,
    roundedDimensionalWeightKg: 0.5,
    roundedActualWeightKg: 0.0,
    billableWeightKg: 0.5
  });
});

test('one step below the 2.0 kg boundary rounds up to 2.0 not to 2.5', function () {
  assert.deepEqual(code.billableWeight({ lengthCm: 9, widthCm: 11, heightCm: 101, actualWeightKg: 0 }), {
    dimensionalWeightKg: 1.9998,
    roundedDimensionalWeightKg: 2.0,
    roundedActualWeightKg: 0.0,
    billableWeightKg: 2.0
  });
});

test('one step above 2.0 rounds up to 2.5 while an exact actual weight of 2.0 stays 2.0', function () {
  assert.deepEqual(code.billableWeight({ lengthCm: 73, widthCm: 137, heightCm: 1, actualWeightKg: 2.0 }), {
    dimensionalWeightKg: 2.0002,
    roundedDimensionalWeightKg: 2.5,
    roundedActualWeightKg: 2.0,
    billableWeightKg: 2.5
  });
});

test('integer and one-decimal forms of the same value leave an exact multiple unchanged', function () {
  assert.deepEqual(code.billableWeight({ lengthCm: 3, widthCm: 100.0, heightCm: 10, actualWeightKg: 3.0 }), {
    dimensionalWeightKg: 0.6,
    roundedDimensionalWeightKg: 1.0,
    roundedActualWeightKg: 3.0,
    billableWeightKg: 3.0
  });
});

test('unequal raw weights that round to the same value bill that shared rounded value', function () {
  assert.deepEqual(code.billableWeight({ lengthCm: 62, widthCm: 10, heightCm: 10, actualWeightKg: 1.01 }), {
    dimensionalWeightKg: 1.24,
    roundedDimensionalWeightKg: 1.5,
    roundedActualWeightKg: 1.5,
    billableWeightKg: 1.5
  });
});
